#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [0.032940885, 0.42313218, 0.095154615], 'basis': [[0.0, 0.9192226553974889, -0.3937381233815053], [-0.9980881060838086, -0.024335858973194093, -0.05681459726226004], [-0.06180722040373598, 0.39298533785883966, 0.9174651991950091]], 'axis': [-0.3937381233815053, -0.05681459726226004, 0.9174651991950091], 'zmin': -0.004243250162041632, 'zmax': 0.004414387000363361, 'profiles': [{'outer': [[-0.07397350610032591, 0.0018837669270371006], [-0.07302214093370134, 0.010460027716857334], [-0.07127436794211509, 0.01902079162764309], [-0.06884367110674951, 0.02731204475535064], [-0.06505133784956046, 0.035046145346811615], [-0.06049491626259106, 0.04247829998520231], [-0.055339966728589526, 0.04943309463140357], [-0.04913591981429717, 0.05537052407401736], [-0.04233189525046016, 0.06080342183399739], [-0.035228797913565466, 0.06557662538796714], [-0.027408890527601957, 0.06902335195463176], [-0.019175151396167225, 0.07178966243295844], [-0.010885361574182335, 0.07381958349682863], [-0.0022718332156135166, 0.07433756160169099], [0.002019876723350517, 0.0742322922846587], [0.006314196003716805, 0.07411075985380518], [0.014864027576334303, 0.0731363305714745], [0.023052119767687167, 0.07066680193408373], [0.0311255153445815, 0.06746582447323762], [0.03874862982528505, 0.0636195666975407], [0.04559630293108638, 0.058473028557874396], [0.05209801560204541, 0.05267102917092134], [0.05797509256786819, 0.0464099646186427], [0.0626516301424597, 0.039197386668667476], [0.06680798057050066, 0.031515586766379076], [0.07019373488630168, 0.023607780578354373], [0.0721593613152019, 0.01520562184681365], [0.0734756299709249, 0.006554158163488548], [0.07397350795454251, -0.002055131011789886], [0.07297657631333665, -0.010640976617338743], [0.07130179412444543, -0.019199332093289778], [0.06884495360657295, -0.027491551496303862], [0.06500443269830268, -0.035218962243470674], [0.06052240356635215, -0.0426758655671444], [0.05541851560074062, -0.04962063361301936], [0.04921019249874342, -0.055547609258055936], [0.04245857065226168, -0.06099765345257866], [0.03530856692796474, -0.06577230455608152], [0.027462523368086557, -0.06920095352631384], [0.01919751735364571, -0.07197372992767848], [0.010880180960685609, -0.07399646181154433], [0.0023358550808299694, -0.074525690885458], [-0.0020094770996653493, -0.07441418517065763], [-0.0063742289818741, -0.07429229892880607], [-0.014889796893243004, -0.07331370434006786], [-0.02308600535490439, -0.07084739831289838], [-0.031106998214443408, -0.06764452099317511], [-0.038755089230171985, -0.06378829576116299], [-0.04564705876390111, -0.05864047188241734], [-0.05207052891635654, -0.05284957210626987], [-0.05797375265504718, -0.04660849128122415], [-0.06269726462899176, -0.039397383566078845], [-0.0667843339674154, -0.031707787725073], [-0.07021949360425705, -0.023785167225669063], [-0.07221004728184925, -0.015373054275619908], [-0.07345327337625528, -0.0067382298314205575]], 'holes': [[[-0.001754501243747479, 0.011848595408237746], [-0.0037532894357680444, 0.01128302369270479], [-0.005683754249797711, 0.01050689486514792], [-0.007376595029295089, 0.00929041636706083], [-0.00892086049763675, 0.007900719719429407], [-0.010124119965417969, 0.0061683979999597235], [-0.011094823132110994, 0.004313851107306389], [-0.011627577157268046, 0.002312190651454227], [-0.011929056763088131, 0.0002345389329387112], [-0.011733226514412087, -0.0018581849856980914], [-0.011309912642669636, -0.003907293335344328], [-0.010432999526041813, -0.005803897727963776], [-0.009351981723165212, -0.007583976532137426], [-0.00788460887962521, -0.009066268881331968], [-0.006234991954118414, -0.01036729660979239], [-0.004366902120764674, -0.011244058290353862], [-0.002378670483549028, -0.0119029690807801], [-0.0003192693487720344, -0.012086778232415076], [0.0017544319956522936, -0.012019953336793895], [0.0037533493210544335, -0.011454365335519346], [0.005685024296451273, -0.010686386130046212], [0.007379095199077876, -0.009478047575099131], [0.008922141761315776, -0.008080218600675869], [0.010103410255288976, -0.006340259194079445], [0.011096094414908962, -0.004512387333104725], [0.011627638278698896, -0.0024835493462020933], [0.011909697564733347, -0.0004145410797487382], [0.011734446656660317, 0.0016787016962333998], [0.011311192670204253, 0.0037278023138046248], [0.010434339438862818, 0.005624398974349059], [0.009332562639524094, 0.007403982117402416], [0.007865188559839685, 0.008886282326303717], [0.006234933304976544, 0.010195944186968], [0.004346252913994274, 0.011072194626532299], [0.002378661738812435, 0.011731608682522108], [0.0003192693487720898, 0.011896379643802584]]]}], 'simplify_tolerance': 2.97726504974298e-05, 'sketch_entity_count': 101}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
